mapper.select:
SELECT c.*, s.name AS store_name, s.platform, l.title, u.nickname AS operator_name, r.name AS rule_name
FROM ecom_price_change c
LEFT JOIN ecom_store s ON s.id = c.store_id
LEFT JOIN ecom_listing l ON l.id = c.listing_id
LEFT JOIN sys_user u ON u.id = c.create_by
LEFT JOIN ecom_reprice_rule r ON r.id = c.rule_id

    c.store_id = #{storeId}
    AND c.listing_id = #{listingId}
    AND c.change_type = #{changeType}
    AND c.source = #{source}
    AND c.status = #{status}
    AND c.batch_no = #{batchNo}
    AND c.create_time >= #{begin}
    AND c.create_time < #{end}
    AND (c.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR l.title LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY c.id DESC
